#!/usr/bin/env python3
"""
Pokerbots Discard Hold'em - bot v9

Architecture
  1. Fast 5/6/7-card evaluators (rank-multiset + flush-mask lookup tables, built at import)
  2. Preflop: exact 3-card strength table + hand-vs-range equity matrix (offline Monte-Carlo).
     Decisions compare our equity against the range the opponent's raise represents,
     where that range size is learned online (open / 3-bet / 4-bet frequencies).
  3. Postflop: equity against the opponent's weighted range, conditioned on
       - hand strength implied by their betting (exponent learned from their showdowns)
       - their PREFLOP line, using their exposed discard to recover their original 3 cards
       - how consistent their discard was with a sensible flop discard
  4. Exact river enumeration; time-governed Monte-Carlo elsewhere (safe on slow machines)
  5. Exploits: over-folders (steals, bluffs), stations (bigger value bets), tight 3-bettors
  6. Wide-opener defence: 3-bets much more often against opponents that open >60% of hands
  7. Robust main loop: any exception falls back to a legal action; unknown messages ignored
"""

import sys
import json
import math
import os
import random
import time
from bisect import bisect_left, bisect_right
from itertools import combinations, combinations_with_replacement

