PF_PCT = {}
PF_EQ = {}


def _load_preflop():
    for item in PREFLOP_RAW.split(";"):
        if not item:
            continue
        k, p, e = item.rsplit(":", 2)
        PF_PCT[k] = int(p) / 1000.0
        PF_EQ[k] = int(e) / 1000.0


_load_preflop()


def class_key(cards):
    cs = sorted(cards, key=lambda c: (-(c // 4), c % 4))
    r = [c // 4 for c in cs]
    s = [c % 4 for c in cs]
    if r[0] == r[1] == r[2]:
        pat = 'T'
    elif r[0] == r[1] or r[1] == r[2]:
        if r[0] == r[1]:
            kick = 2
            pair_suits = (s[0], s[1])
        else:
            kick = 0
            pair_suits = (s[1], s[2])
        pat = 'S' if s[kick] in pair_suits else 'R'
    else:
        if s[0] == s[1] == s[2]:
            pat = '3'
        elif s[0] == s[1]:
            pat = '01'
        elif s[0] == s[2]:
            pat = '02'
        elif s[1] == s[2]:
            pat = '12'
        else:
            pat = 'R'
    return "%d,%d,%d|%s" % (r[0], r[1], r[2], pat)


def preflop_pct(hole_ints):
    return PF_PCT.get(class_key(hole_ints), 0.5)



