RANGE_FS = [0.03, 0.06, 0.10, 0.15, 0.22, 0.32, 0.45, 0.62, 0.80, 1.00]
RANGE_RAW = "202,209,230,268,290,314,318,331,340,361;216,216,242,277,306,323,341,348,371,383;215,215,248,283,309,332,352,355,379,411;206,217,250,286,320,339,359,370,387,418;209,216,258,297,320,341,358,375,392,429;209,222,263,296,321,346,366,388,405,444;210,227,272,303,340,357,372,397,422,451;211,230,275,306,331,353,371,404,431,464;215,243,285,319,346,361,386,416,441,472;214,255,292,325,346,369,391,426,453,480;216,251,290,321,349,376,402,436,466,496;214,250,301,333,358,381,410,441,476,506;215,269,317,341,363,392,425,465,490,518;223,270,313,344,370,402,437,475,499,529;223,271,319,350,379,422,452,482,518,538;228,300,343,362,400,440,476,507,534,556;240,294,343,382,423,467,506,533,549,570;255,324,366,406,455,498,532,556,566,587;222,272,370,439,489,524,563,586,610,638;355,550,628,653,674,699,715,723,741,747"
RANGE_M = [[int(x) / 1000.0 for x in row.split(",")] for row in RANGE_RAW.split(";")]


def range_equity(p, f):
    """Approximate all-in equity of a hand at preflop percentile p vs the top fraction f of hands."""
    nb = len(RANGE_M)
    x = min(nb - 1.0, max(0.0, p * nb - 0.5))
    b0 = int(x)
    b1 = min(nb - 1, b0 + 1)
    tx = x - b0
    if f <= RANGE_FS[0]:
        j0 = j1 = 0
        tf = 0.0
    elif f >= RANGE_FS[-1]:
        j0 = j1 = len(RANGE_FS) - 1
        tf = 0.0
    else:
        j1 = bisect_left(RANGE_FS, f)
        j0 = j1 - 1
        tf = (f - RANGE_FS[j0]) / (RANGE_FS[j1] - RANGE_FS[j0])
    r0 = RANGE_M[b0][j0] * (1 - tf) + RANGE_M[b0][j1] * tf
    r1 = RANGE_M[b1][j0] * (1 - tf) + RANGE_M[b1][j1] * tf
    return r0 * (1 - tx) + r1 * tx


# ---------------------------------------------------------------------------
# OPPONENT MODEL (all state lives inside one leg)
# ---------------------------------------------------------------------------
class OpponentModel:
    def __init__(self):
        self.hands = 0
        # preflop
        self.pre_n = 0
        self.pre_vpip = 0
        self.pre_raise = 0
        self.faced_my_raise = 0
        self.folded_to_my_raise = 0
        # preflop nodes: opp opens / opp faces my open (3-bet) / opp faces my 3-bet (4-bet)
        self.open_n = 0
        self.open_r = 0
        self.f3_n = 0
        self.f3_r = 0
        self.f3_fold = 0
        self.f4_n = 0
        self.f4_r = 0
        self.f4_fold = 0
        # postflop
        self.post_actions = 0
        self.post_raises = 0
        self.faced_bet = 0
        self.folded_to_bet = 0
        self.called_bet = 0
        # showdown strength of aggressive hands
        self.k_sum = 0.0
        self.k_n = 0
        # discard rationality
        self.disc_n = 0
        self.disc_greedy = 0

    # ---- derived stats with priors
    @property
    def vpip(self):
        return (self.pre_vpip + 6.0) / (self.pre_n + 10.0)

    @property
    def f_open(self):
        return (self.open_r + 0.45 * 6.0) / (self.open_n + 6.0)

    @property
    def f_3bet(self):
        return (self.f3_r + 0.10 * 8.0) / (self.f3_n + 8.0)

    @property
    def f_4bet(self):
        return (self.f4_r + 0.06 * 8.0) / (self.f4_n + 8.0)

    @property
    def fold_to_3bet(self):
        return (self.f4_fold + 0.40 * 6.0) / (self.f4_n + 6.0)

    @property
    def fold_to_open(self):
        return (self.f3_fold + 0.40 * 6.0) / (self.f3_n + 6.0)

    @property
    def pfr(self):
        return (self.pre_raise + 3.0) / (self.pre_n + 10.0)

    @property
    def pre_fold_to_raise(self):
        return (self.folded_to_my_raise + 3.0) / (self.faced_my_raise + 8.0)

    @property
    def fold_to_bet(self):
        return (self.folded_to_bet + 3.0) / (self.faced_bet + 8.0)

    @property
    def agg(self):
        return (self.post_raises + 2.0) / (self.post_actions + 8.0)

    @property
    def mean_bet_pct(self):
        m0, n0 = PARAMS["k_prior_m"], PARAMS["k_prior_n"]
        return (self.k_sum + m0 * n0) / (self.k_n + n0)

    @property
    def k_base(self):
        """Exponent such that weights ~ pct**k reproduce the mean showdown percentile of bets."""
        m = min(0.93, max(0.5, self.mean_bet_pct))
        return max(0.0, min(4.0, (2 * m - 1) / (1 - m)))

    @property
    def p_greedy(self):
        """Probability the opponent keeps the 'sensible' cards on the flop."""
        obs = (self.disc_greedy + 6 * 0.8) / (self.disc_n + 6.0)
        return max(0.0, min(0.97, (obs - 0.33) / 0.67))

    @property
    def inconsistent_weight(self):
        p = self.p_greedy
        q = (1 - p) / 3.0
        return max(0.04, min(1.0, q / (p + q)))

    def _nodes(self, hist, i_am_button):
        r = 0
        for h in hist:
            if h.get("street") != "preflop":
                break
            actor, act = h.get("actor"), h.get("action")
            if actor == "opp":
                if r == 0 and not i_am_button:
                    self.open_n += 1
                    if act == "raise":
                        self.open_r += 1
                elif r == 1:
                    self.f3_n += 1
                    if act == "raise":
                        self.f3_r += 1
                    elif act == "fold":
                        self.f3_fold += 1
                elif r == 2:
                    self.f4_n += 1
                    if act == "raise":
                        self.f4_r += 1
                    elif act == "fold":
                        self.f4_fold += 1
            if act == "raise":
                r += 1

    def record_hand(self, msg, my_discard, opp_discard, i_am_button=True):
        self.hands += 1
        hist = msg.get("history", [])
        self._nodes(hist, i_am_button)
        opp_saw = False
        opp_vpip = False
        opp_pfr = False
        i_raised_pre = False
        opp_raised_post = False
        my_bet_street = None
        for h in hist:
            st, actor, act = h.get("street"), h.get("actor"), h.get("action")
            if st == "preflop":
                if actor == "me" and act == "raise":
                    i_raised_pre = True
                elif actor == "opp":
                    opp_saw = True
                    if act in ("call", "raise"):
                        opp_vpip = True
                    if act == "raise":
                        opp_pfr = True
                    if i_raised_pre:
                        self.faced_my_raise += 1
                        if act == "fold":
                            self.folded_to_my_raise += 1
                        i_raised_pre = False
            else:
                if actor == "me" and act == "raise":
                    my_bet_street = st
                elif actor == "opp":
                    self.post_actions += 1
                    if act == "raise":
                        self.post_raises += 1
                        opp_raised_post = True
                    if my_bet_street == st:
                        self.faced_bet += 1
                        if act == "fold":
                            self.folded_to_bet += 1
                        elif act == "call":
                            self.called_bet += 1
                        my_bet_street = None
        if opp_saw:
            self.pre_n += 1
            if opp_vpip:
                self.pre_vpip += 1
            if opp_pfr:
                self.pre_raise += 1

        # showdown analysis
        oh = msg.get("opp_hole_cards")
        board = msg.get("board") or []
        mine = msg.get("my_hole_cards") or []
        if oh and len(oh) == 2 and len(board) == 5 and len(mine) == 2:
            try:
                o = [CARD_TO_INT[c] for c in oh]
                b = [CARD_TO_INT[c] for c in board]
                m = [CARD_TO_INT[c] for c in mine]
                dead = set(b) | set(m) | set(o)
                extra = []
                for d in (my_discard, opp_discard):
                    if d in CARD_TO_INT:
                        dead.add(CARD_TO_INT[d])
                        extra.append(CARD_TO_INT[d])
                if opp_raised_post:
                    rem = [c for c in range(52) if c not in (set(b) | set(m) | set(extra))]
                    osc = eval_7((o[0], o[1]) + tuple(b))
                    lo = hi = 0
                    bt = tuple(b)
                    for x, y in combinations(rem, 2):
                        s = eval_7((x, y) + bt)
                        if s < osc:
                            lo += 1
                        elif s == osc:
                            hi += 1
                    tot = len(rem) * (len(rem) - 1) // 2
                    if tot:
                        self.k_sum += (lo + 0.5 * hi) / tot
                        self.k_n += 1
                if opp_discard in CARD_TO_INT and len(b) >= 3:
                    d = CARD_TO_INT[opp_discard]
                    flop = b[:3]
                    kept = flop_key(o[0], o[1], flop)
                    alt = max(flop_key(o[0], d, flop), flop_key(o[1], d, flop))
                    self.disc_n += 1
                    if kept >= alt:
                        self.disc_greedy += 1
            except Exception:
                pass


# ---------------------------------------------------------------------------
# EQUITY ENGINES
# ---------------------------------------------------------------------------
PRE_FLOOR = 0.10


def _pct_ranks(scores):
    srt = sorted(scores)
    n = len(srt)
    out = []
    for s in scores:
        out.append((bisect_left(srt, s) + bisect_right(srt, s)) * 0.5 / n)
    return out


def range_weight(pct, k, kc):
    w = 1.0
    if k > 0:
        w *= (pct + 0.03) ** k
    if kc > 0:
        w *= (1.05 - pct) ** kc
    return w


def post_equity(hole2, board, dead_extra, opp_disc, k, kc, inc_w, deadline, pre_f=None, min_cnt=160):
    """Equity of 2 hole cards on a 4 or 5 card board against the opponent's weighted range."""
    dead = set(hole2) | set(board) | set(dead_extra)
    rem = [c for c in range(52) if c not in dead]
    pairs = list(combinations(rem, 2))
    flop = board[:3]
    bt = tuple(board)
    h = (hole2[0], hole2[1])
    n = len(bt)
    if n == 5:
        my = eval_7(h + bt)
        sc = [eval_7(p + bt) for p in pairs]
    else:
        my = None
        sc = [eval_6(p + bt) for p in pairs]
    pcts = _pct_ranks(sc)
    weights = []
    for i, (a, b) in enumerate(pairs):
        w = range_weight(pcts[i], k, kc)
        if opp_disc is not None:
            kept = flop_key(a, b, flop)
            alt = max(flop_key(a, opp_disc, flop), flop_key(b, opp_disc, flop))
            if kept < alt:
                w *= inc_w
            if pre_f is not None:
                if PF_PCT.get(class_key((a, b, opp_disc)), 0.5) < 1.0 - pre_f:
                    w *= PRE_FLOOR
        weights.append(w)
    if n == 5:
        tw = 0.0
        ww = 0.0
        for i in range(len(pairs)):
            w = weights[i]
            tw += w
            s = sc[i]
            if my > s:
                ww += w
            elif my == s:
                ww += 0.5 * w
        return ww / max(tw, 1e-12)
    # turn: weighted sampling of (opp pair, river)
    cum = []
    t = 0.0
    for w in weights:
        t += w
        cum.append(t)
    if t <= 0:
        return 0.5
    import random as _r
    rnd = _r.random
    wins = 0.0
    cnt = 0
    npairs = len(pairs)
    nrem = len(rem)
    clock = time.perf_counter
    while True:
        for _ in range(32):
            idx = bisect_left(cum, rnd() * t)
            if idx >= npairs:
                idx = npairs - 1
            a, b = pairs[idx]
            while True:
                r = rem[int(rnd() * nrem)]
                if r != a and r != b:
                    break
            full = bt + (r,)
            ms = eval_7(h + full)
            os_ = eval_7((a, b) + full)
            if ms > os_:
                wins += 1.0
            elif ms == os_:
                wins += 0.5
            cnt += 1
        if clock() >= deadline and cnt >= min_cnt:
            break
        if cnt >= 6000:
            break
    return wins / cnt


def flop_option_equities(hole3, flop, dead_extra, k, inc_w, deadline, min_samples=120, max_samples=4000, pre_f=None):
    """Equity for each of the 3 discard choices (index i = discard hole3[i]) against the
    opponent's weighted range, with shared rollouts (no hindsight selection)."""
    dead = set(hole3) | set(flop) | set(dead_extra)
    rem = [c for c in range(52) if c not in dead]
    f = tuple(flop)
    c0, c1, c2 = hole3
    opts = ((c1, c2), (c0, c2), (c0, c1))
    sample = random.sample
    rnd = random.random
    clock = time.perf_counter
    okeys = []
    res = [[], [], []]
    n = 0
    while True:
        for _ in range(24):
            o0, o1, o2, t, r = sample(rem, 5)
            if pre_f is not None:
                tries = 0
                while tries < 12 and PF_PCT.get(class_key((o0, o1, o2)), 0.5) < 1.0 - pre_f and rnd() > PRE_FLOOR:
                    o0, o1, o2, t, r = sample(rem, 5)
                    tries += 1
            a, b, key = greedy_keep(o0, o1, o2, f)
            full = f + (t, r)
            os_ = eval_7((a, b) + full)
            okeys.append(key)
            for i in range(3):
                ms = eval_7(opts[i] + full)
                res[i].append(1.0 if ms > os_ else (0.5 if ms == os_ else 0.0))
            n += 1
        if (clock() >= deadline and n >= min_samples) or n >= max_samples:
            break
    if k > 0:
        pcts = _pct_ranks(okeys)
        ws = [(p + 0.03) ** k for p in pcts]
    else:
        ws = [1.0] * n
    tw = sum(ws)
    eqs = []
    for i in range(3):
        r = res[i]
        eqs.append(sum(ws[j] * r[j] for j in range(n)) / tw)
    return eqs


# ---------------------------------------------------------------------------
# BOT CONTROLLER
# ---------------------------------------------------------------------------
class DiscardHoldemBot:
    def __init__(self):
        self.total_hands = 200
        self.opp = OpponentModel()
        self.hand_id = 0
        self.seat = "button"
        self.hole_cards = []
        self.my_discard = None
        self.opp_discard = None
        self.time_left_ms = 30000.0
        self.bank_ms = 30000.0
        self.reached = 0
        self.seen = 0
        self.flop_opp_raises = 0
        self.flop_bet_frac = 0.0
        self.hand_k_hist = 0
        self.pre_f = None
        # online calibration
        self.cal_n = 0
        self.cal_gap = 0.0           # sum(actual result - estimated equity) over river calls that reached showdown
        self.pend_river_est = None
        self.def_n = 0
        self.def_sum = 0.0           # net chips of hands where we called an open from the big blind
        self.def_pending = False
        self._cur_raw_eq = None
        self._pf_called_open = False

    # ---- protocol handlers -------------------------------------------------
    def handle_init(self, msg):
        self.total_hands = int(msg.get("total_hands", 200))
        self.time_left_ms = float(msg.get("time_bank_ms", 30000))
        self.bank_ms = self.time_left_ms

    def handle_new_hand(self, msg):
        self.hand_id = msg.get("hand_id", 0)
        self.seat = msg.get("seat", "button")
        self.hole_cards = list(msg.get("hole_cards", []))
        self.my_discard = None
        self.opp_discard = None
        self.flop_opp_raises = 0
        self.flop_bet_frac = 0.0
        self.seen += 1
        self.pend_river_est = None
        self.def_pending = False
        self.pre_f = None

    def handle_discard_result(self, msg):
        self.my_discard = msg.get("my_discard")
        self.opp_discard = msg.get("opp_discard")
        self.hole_cards = list(msg.get("hole_cards", []))

    def handle_hand_result(self, msg):
        try:
            net = msg.get("net")
            if isinstance(net, (int, float)):
                if self.def_pending:
                    self.def_n += 1
                    self.def_sum += float(net)
                if self.pend_river_est is not None and msg.get("result") == "showdown":
                    win = 1.0 if net > 0 else (0.5 if net == 0 else 0.0)
                    self.cal_n += 1
                    self.cal_gap += win - self.pend_river_est
        except Exception:
            pass
        self.pend_river_est = None
        self.def_pending = False
        if DEBUG and self.hand_id % 50 == 0:
            print("S hand=%s cal_n=%d cal_gap=%.2f bias=%.3f def_n=%d def_avg=%.2f def_margin=%.3f f_open=%.2f" % (self.hand_id, self.cal_n, self.cal_gap, self._river_bias(), self.def_n, self.def_sum/max(1,self.def_n), self._def_margin(), self.opp.f_open), file=sys.stderr, flush=True)
        try:
            self.opp.record_hand(msg, self.my_discard, self.opp_discard, self.seat == "button")
        except Exception as exc:
            print("[hand_result error] %r" % (exc,), file=sys.stderr, flush=True)

    # ---- time governor -----------------------------------------------------
    def _deadline(self, weight, cap_ms=650.0):
        left = self.time_left_ms
        hands_left = max(1, self.total_hands - self.hand_id + 1)
        reach = max(0.35, (self.reached + 6.0) / (self.seen + 10.0))
        reserve = max(3500.0, 0.10 * self.bank_ms)
        per_hand = max(0.0, PARAMS["time_frac"] * (left - reserve) / hands_left)
        budget = per_hand / reach * weight
        if left < reserve:
            budget = 0.0
        budget = min(cap_ms, budget)
        return time.perf_counter() + budget / 1000.0

    def _floor(self):
        """Minimum Monte-Carlo samples per decision; shrinks when the time bank is low."""
        if self.time_left_ms < max(3500.0, 0.10 * self.bank_ms):
            return 16
        if self.time_left_ms < 0.3 * self.bank_ms:
            return 32
        return 48

    def _river_bias(self):
        """Learned correction (usually negative) to equity estimates when facing a river bet."""
        if not PARAMS["online_cal"]:
            return 0.0
        bias = self.cal_gap / (self.cal_n + 5.0)
        return max(-0.30, min(0.10, bias))

    def _def_margin(self):
        """Extra preflop margin for calling opens from the big blind, from our realised results
        compared with simply folding (which loses the 2-chip blind)."""
        if not PARAMS["online_cal"] or self.def_n < 10:
            return 0.0
        avg = self.def_sum / self.def_n
        diff = (-2.0 - avg) * self.def_n / (self.def_n + 12.0)
        return max(-0.04, min(0.14, 0.06 * diff))

    # ---- helpers -----------------------------------------------------------
    @staticmethod
    def _clamp_raise(target, req):
        lo = int(req["min_raise"])
        hi = int(req["max_raise"])
        return max(lo, min(hi, int(round(target))))

    @staticmethod
    def _safe(action, amount, req):
        legal = req.get("legal_actions", [])
        if action not in legal:
            if "check" in legal:
                return {"type": "action", "action": "check"}
            if "call" in legal and req.get("to_call", 0) <= 1:
                return {"type": "action", "action": "call"}
            return {"type": "action", "action": "fold" if "fold" in legal else legal[0]}
        if action == "raise":
            return {"type": "action", "action": "raise",
                    "amount": DiscardHoldemBot._clamp_raise(amount, req)}
        return {"type": "action", "action": action}

    def _dead_extra(self):
        out = []
        for d in (self.my_discard, self.opp_discard):
            if d in CARD_TO_INT:
                out.append(CARD_TO_INT[d])
        return out

    def _agg_k(self, history, street, opp_bet, my_bet, pot):
        """Exponent k for weighting the opponent's range by hand strength after its betting."""
        kb = self.opp.k_base
        opp_r = sum(1 for h in history if h.get("street") == street and h.get("actor") == "opp" and h.get("action") == "raise")
        prior_r = sum(1 for h in history if h.get("street") not in (street, "preflop") and h.get("actor") == "opp" and h.get("action") == "raise")
        if opp_r > 0 and opp_bet > 0:
            pot_before = max(2.0, pot - opp_bet - my_bet)
            frac = opp_bet / pot_before
            sf = 0.55 + 0.7 * min(frac, 1.6)
            k = kb * sf * (1.0 + 0.3 * (opp_r - 1)) * (1.0 + 0.2 * prior_r)
        else:
            k = kb * 0.3 * prior_r
        return min(k, 6.0)

    def _opp_pre_range(self, history):
        """Fraction f such that the opponent's preflop line suggests a top-f hand (None = unknown/wide)."""
        pre = [h for h in history if h.get("street") == "preflop"]
        raises = [(i, h) for i, h in enumerate(pre) if h.get("action") == "raise"]
        if not raises:
            return None
        O = self.opp
        level = len(raises)
        last_actor = raises[-1][1].get("actor")
        if last_actor == "opp":
            if level == 1:
                f = O.f_open if self.seat != "button" else 0.40
            elif level == 2:
                f = O.f_3bet
            elif level == 3:
                f = O.f_4bet
            else:
                f = 0.04
            return max(0.04, min(1.0, f))
        # we raised last and the opponent continued (called)
        if level == 1:
            f = 1.0 - O.fold_to_open
        elif level == 2:
            f = 1.0 - O.fold_to_3bet
        else:
            f = 0.30
        return max(0.15, min(1.0, f))

    # ---- discard -----------------------------------------------------------
    def choose_discard(self, req):
        hole = req.get("hole_cards", self.hole_cards)
        board = req.get("board", [])
        self.reached += 1
        if len(hole) != 3 or len(board) < 3:
            worst = min(hole, key=lambda c: (RANK_TO_INT[c[0]], SUIT_TO_INT[c[1]]))
            return {"type": "discard", "card": worst}
        h = [CARD_TO_INT[c] for c in hole]
        f = [CARD_TO_INT[c] for c in board[:3]]
        k = 0.0
        if self.flop_opp_raises > 0:
            k = self.opp.k_base * (0.55 + 0.7 * min(self.flop_bet_frac, 1.6))
        dl = self._deadline(0.40, cap_ms=900.0)
        eqs = flop_option_equities(h, f, [], k, 1.0, dl, min_samples=self._floor(), max_samples=6000, pre_f=self.pre_f)
        best = max(range(3), key=lambda i: (round(eqs[i], 5), -CARD_RANK[h[i]]))
        return {"type": "discard", "card": hole[best]}

    # ---- actions -----------------------------------------------------------
    def choose_action(self, req):
        street = req.get("street", "preflop")
        self._cur_raw_eq = None
        self._pf_called_open = False
        if street == "preflop":
            reply = self._preflop(req)
        else:
            reply = self._postflop(req)
        if reply.get("action") == "call":
            if street == "river" and self._cur_raw_eq is not None:
                self.pend_river_est = self._cur_raw_eq
            if street == "preflop" and self._pf_called_open:
                self.def_pending = True
        return reply

    def _preflop(self, req):
        legal = req.get("legal_actions", [])
        to_call = req.get("to_call", 0)
        pot = req.get("pot", 3)
        opp_bet = req.get("opp_bet", 0)
        history = req.get("history", [])
        hole = [CARD_TO_INT[c] for c in self.hole_cards]
        p = preflop_pct(hole)
        opp_r = sum(1 for h in history if h.get("street") == "preflop" and h.get("actor") == "opp" and h.get("action") == "raise")
        my_r = sum(1 for h in history if h.get("street") == "preflop" and h.get("actor") == "me" and h.get("action") == "raise")
        P = PARAMS
        O = self.opp
        i_am_button = self.seat == "button"

        # ---- unopened pot: small blind first to act, or the big blind facing a limp
        if opp_bet <= BIG_BLIND and opp_r == 0:
            if i_am_button or to_call > 0:
                open_p = P["open_raise_p"]
                if O.hands >= 10 and O.fold_to_open > 0.55:
                    open_p = min(open_p, 0.12)       # steal against over-folders
                elif O.hands >= 10 and O.f_3bet > 0.30:
                    open_p = max(open_p, 0.55)       # opponent punishes our opens: tighten
                if p >= open_p and "raise" in legal:
                    size = 7 if p >= 0.90 else 6
                    return self._safe("raise", size, req)
                if p >= P["limp_p"] and "call" in legal:
                    return self._safe("call", None, req)
                return self._safe("fold", None, req)
            iso = P["iso_p"]
            if O.hands >= 10 and O.fold_to_open > 0.5:
                iso = min(iso, 0.25)
            if p >= iso and "raise" in legal:
                size = 8 if p >= 0.9 else 6
                return self._safe("raise", size, req)
            return self._safe("check", None, req)

        # ---- facing a raise: compare our equity against the range that raise represents
        level = my_r + opp_r
        if level <= 1:
            f = O.f_open
        elif level == 2:
            f = O.f_3bet
        elif level == 3:
            f = O.f_4bet
        else:
            f = 0.03
        # a raise is never weaker than a sensible minimum range, and sizing tells more
        f = max(0.03, min(1.0, f))
        if opp_bet >= 40:
            f = min(f, 0.12)
        elif opp_bet >= 24:
            f = min(f, 0.22)
        E = range_equity(p, f)
        pot_odds = to_call / max(1.0, float(pot + to_call))
        margin = P["pf_margin"] + (0.03 if not i_am_button else 0.0) + 0.012 * max(0, level - 1)
        if level == 1 and not i_am_button:
            margin += self._def_margin()
        if to_call >= req.get("my_stack", 200) - 0.5:
            margin = 0.005          # a call that commits our stack is pure showdown equity
        need = pot_odds + margin

        if "raise" in legal:
            thr3 = P["pf_3bet_eq"]
            if O.hands >= 8 and O.f_open >= 0.60:
                thr3 = min(thr3, P["pf_3bet_eq_wide"])      # wide opener: 3-bet much more often
            if level == 1 and my_r == 0 and E >= thr3 and opp_bet <= 30:
                return self._safe("raise", min(60, opp_bet * 3), req)
            if level == 1 and my_r == 0 and O.hands >= 8 and O.fold_to_3bet > 0.62 and p >= 0.45 and opp_bet <= 12:
                if random.random() < P["pf_bluff3"]:
                    return self._safe("raise", min(60, opp_bet * 3), req)
            if level == 2 and E >= P["pf_4bet_eq"]:
                return self._safe("raise", min(200, int(opp_bet * 2.4)), req)
            if level >= 3 and E >= P["pf_5bet_eq"]:
                return self._safe("raise", 200, req)
        if E >= need and "call" in legal:
            self._pf_called_open = (level == 1 and not i_am_button)
            return self._safe("call", None, req)
        return self._safe("fold", None, req)

    def _postflop(self, req):
        street = req.get("street")
        legal = req.get("legal_actions", [])
        to_call = req.get("to_call", 0)
        pot = req.get("pot", 3)
        my_bet = req.get("my_bet", 0)
        opp_bet = req.get("opp_bet", 0)
        history = req.get("history", [])
        board = [CARD_TO_INT[c] for c in req.get("board", [])]
        hole = [CARD_TO_INT[c] for c in self.hole_cards]
        P = PARAMS

        opp_r = sum(1 for h in history if h.get("street") == street and h.get("actor") == "opp" and h.get("action") == "raise")
        my_r = sum(1 for h in history if h.get("street") == street and h.get("actor") == "me" and h.get("action") == "raise")
        opp_checked = any(h.get("street") == street and h.get("actor") == "opp" and h.get("action") == "check" for h in history)
        k = self._agg_k(history, street, opp_bet, my_bet, pot)
        pre_f = self._opp_pre_range(history)
        self.pre_f = pre_f
        kc = 0.45 if (opp_checked and to_call == 0) else 0.0

        if street == "flop":
            # still holding three cards: record aggression for the coming discard
            self.flop_opp_raises = max(self.flop_opp_raises, opp_r)
            if opp_r > 0 and opp_bet > 0:
                self.flop_bet_frac = opp_bet / max(2.0, pot - opp_bet - my_bet)

        if street == "flop" and len(hole) == 3:
            dl = self._deadline(0.20)
            eqs = flop_option_equities(hole, board[:3], [], k, 1.0, dl, min_samples=self._floor(), max_samples=3000, pre_f=pre_f)
            equity = max(eqs)
        else:
            weight = 0.22 if street == "turn" else 0.12
            dl = self._deadline(weight)
            opp_disc = CARD_TO_INT[self.opp_discard] if self.opp_discard in CARD_TO_INT else None
            equity = post_equity(hole, board, self._dead_extra(), opp_disc, k, kc,
                                 self.opp.inconsistent_weight, dl, pre_f, self._floor() * 3)

        self._cur_raw_eq = equity
        if to_call > 0:
            if street == "river":
                equity += self._river_bias()
            elif street == "turn":
                equity += 0.5 * self._river_bias()
        pot_odds = to_call / max(1.0, float(pot + to_call))
        opp = self.opp
        fold_to_bet = opp.fold_to_bet
        if DEBUG and to_call > 0:
            print("D %s %s %.3f %.3f %d %d %d %.2f" % (self.hand_id, street[0], equity, pot_odds, to_call, pot, opp_r, k), file=sys.stderr, flush=True)

        # ---- can bet / check ------------------------------------------------
        if to_call == 0:
            if "raise" not in legal:
                return self._safe("check", None, req)
            vt = P["val_thr_river"] if street == "river" else P["val_thr"]
            if equity >= vt:
                if equity >= 0.85:
                    frac = 0.85
                elif equity >= 0.72:
                    frac = 0.65
                else:
                    frac = 0.45
                if opp.agg < 0.12 and opp.fold_to_bet < 0.2 and opp.hands >= 12:
                    frac += 0.25                      # station: bigger value bets
                bet = my_bet + max(2, int(round(pot * frac)))
                return self._safe("raise", bet, req)
            if (opp.faced_bet >= P["exp_min_obs"] and fold_to_bet >= P["exp_min_fold"] and pot <= 90
                    and equity < vt):
                B = max(2, int(round(pot * 0.6)))
                e2 = max(0.0, equity - 0.20 * fold_to_bet)
                ev_bet = fold_to_bet * pot + (1 - fold_to_bet) * (e2 * (pot + 2 * B) - (1 - e2) * B)
                ev_chk = equity * pot
                if ev_bet > ev_chk + 0.5 and random.random() < P["exp_freq"]:
                    return self._safe("raise", my_bet + B, req)
            if (street in ("turn", "river") and equity <= 0.22 and opp.faced_bet >= 8
                    and fold_to_bet >= 0.55 and opp_checked and pot <= 80):
                if random.random() < P["bluff_prob"] * 0.8:
                    bet = my_bet + max(2, int(round(pot * 0.6)))
                    return self._safe("raise", bet, req)
            return self._safe("check", None, req)

        # ---- facing a bet -----------------------------------------------------
        margin = P["call_margin"] + (0.015 if street == "river" else 0.0) + 0.02 * max(0, opp_r - 1)
        if to_call >= req.get("my_stack", 200) - 0.5:
            margin = 0.015          # all-in call: no more betting, equity is what it is
        rt = P["raise_thr"] + (0.03 if street == "river" else 0.0)
        if my_r >= 1 or opp_r >= 2:
            rt += 0.07
        if equity >= rt and "raise" in legal:
            mult = 0.7 if equity < 0.9 else 1.0
            target = opp_bet + int(round((pot + to_call) * mult))
            return self._safe("raise", target, req)
        if ("raise" in legal and opp_r == 1 and my_r == 0 and to_call < req.get("my_stack", 200) - 0.5
                and opp.faced_bet >= P["exp_min_obs"] and fold_to_bet >= P["exp_min_fold"]):
            target = opp_bet + int(round((pot + to_call) * 0.8))
            target = max(int(req["min_raise"]), min(int(req["max_raise"]), target))
            R = target - my_bet
            if R <= 70:
                e2 = max(0.0, equity - 0.20 * fold_to_bet)
                ev_raise = fold_to_bet * pot + (1 - fold_to_bet) * (e2 * (pot + R - to_call) - (1 - e2) * R)
                ev_call = equity * pot - (1 - equity) * to_call if equity >= pot_odds - 0.05 else 0.0
                if ev_raise > max(ev_call, 0.0) + 1.0 and random.random() < P["exp_freq"]:
                    return self._safe("raise", target, req)
        if equity >= pot_odds + margin and "call" in legal:
            return self._safe("call", None, req)
        # never fold to a tiny bet when our equity is close to pot odds
        if to_call <= max(2, pot // 8) and equity >= pot_odds - 0.01 and "call" in legal:
            return self._safe("call", None, req)
        return self._safe("fold", None, req)


# ---------------------------------------------------------------------------
# MAIN LOOP
# ---------------------------------------------------------------------------
def _fallback_action(msg):
    legal = msg.get("legal_actions", [])
    if "check" in legal:
        return {"type": "action", "action": "check"}
    if "call" in legal and msg.get("to_call", 0) <= 2:
        return {"type": "action", "action": "call"}
    return {"type": "action", "action": "fold" if "fold" in legal else legal[0]}


def main():
    bot = DiscardHoldemBot()
    for raw_line in sys.stdin:
        line = raw_line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except Exception:
            continue
        if not isinstance(msg, dict):
            continue
        t = msg.get("type")
        if "time_left_ms" in msg:
            try:
                bot.time_left_ms = float(msg["time_left_ms"])
            except Exception:
                pass
        try:
            if t == "action_request":
                reply = bot.choose_action(msg)
                print(json.dumps(reply, separators=(",", ":")), flush=True)
            elif t == "discard_request":
                reply = bot.choose_discard(msg)
                print(json.dumps(reply, separators=(",", ":")), flush=True)
            elif t == "init":
                bot.handle_init(msg)
            elif t == "new_hand":
                bot.handle_new_hand(msg)
            elif t == "discard_result":
                bot.handle_discard_result(msg)
            elif t == "hand_result":
                bot.handle_hand_result(msg)
            elif t == "match_end":
                break
        except Exception as exc:
            print("[ERROR] %r" % (exc,), file=sys.stderr, flush=True)
            if t == "action_request":
                print(json.dumps(_fallback_action(msg)), flush=True)
            elif t == "discard_request":
                cards = msg.get("hole_cards", ["2s", "3s", "4s"])
                worst = min(cards, key=lambda c: (RANK_TO_INT.get(c[0], 0), SUIT_TO_INT.get(c[1], 0)))
                print(json.dumps({"type": "discard", "card": worst}), flush=True)


if __name__ == "__main__":
    main()